"""Binary Tree Maximum Path Sum — return the best *downward* arm, record the best bend.

A branch contributing a negative sum is dropped (clamped to 0) because omitting
it always beats including it.

Time: O(n)   Space: O(h)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def maxPathSum(self, root) -> int:
        best = float("-inf")

        def gain(node) -> int:
            nonlocal best
            if not node:
                return 0
            left = max(gain(node.left), 0)
            right = max(gain(node.right), 0)
            best = max(best, node.val + left + right)
            return node.val + max(left, right)

        gain(root)
        return best
